import { crc32, deflateRawSync } from "node:zlib";

/**
 * Write-only ZIP (PKWARE APPNOTE 6.3, deflate, no ZIP64) built on Node's own
 * zlib. It never reads archives, and every entry name is generated by the
 * server: plain ASCII, no paths, unique. Each entry is compressed as it is
 * added and only the compressed bytes are kept, so callers can generate one
 * document at a time and stop as soon as a budget is exceeded.
 */
export const MAX_ZIP_ENTRIES = 500;
/** Budget for the uncompressed input and for the finished archive. */
export const MAX_ZIP_BYTES = 32 * 1024 * 1024;
const SAFE_NAME = /^[A-Za-z0-9][A-Za-z0-9._-]{0,99}$/;
const EOCD_BYTES = 22;

export class ZipLimitError extends Error {}

/** DOS date/time fields in Dubai wall-clock time (UTC+4, no daylight saving). */
function dosStamp(instant: Date) {
  const at = new Date(instant.getTime() + 4 * 3_600_000);
  const time =
    (at.getUTCHours() << 11) |
    (at.getUTCMinutes() << 5) |
    Math.floor(at.getUTCSeconds() / 2);
  const date =
    ((at.getUTCFullYear() - 1980) << 9) |
    ((at.getUTCMonth() + 1) << 5) |
    at.getUTCDate();
  return { time, date };
}

export class ZipWriter {
  private readonly locals: Buffer[] = [];
  private readonly centrals: Buffer[] = [];
  private readonly names = new Set<string>();
  private readonly time: number;
  private readonly date: number;
  private offset = 0;
  private directory = 0;
  private input = 0;
  constructor(at = new Date()) {
    ({ time: this.time, date: this.date } = dosStamp(at));
  }
  get size() {
    return this.offset + this.directory + EOCD_BYTES;
  }
  add(name: string, data: Buffer) {
    if (this.names.size >= MAX_ZIP_ENTRIES)
      throw new ZipLimitError("ZIP entry count out of bounds");
    if (!SAFE_NAME.test(name) || name.includes(".."))
      throw new Error("Unsafe ZIP entry name");
    if (this.names.has(name)) throw new Error("Duplicate ZIP entry name");
    // Checked before any state changes: a refused entry leaves the writer as it was.
    if (this.input + data.length > MAX_ZIP_BYTES)
      throw new ZipLimitError("ZIP too large");
    const nameBytes = Buffer.from(name, "ascii");
    const packed = deflateRawSync(data);
    const crc = crc32(data);
    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0);
    local.writeUInt16LE(20, 4); // version needed: 2.0 (deflate)
    local.writeUInt16LE(0, 6); // flags: sizes known up front, ASCII name
    local.writeUInt16LE(8, 8); // deflate
    local.writeUInt16LE(this.time, 10);
    local.writeUInt16LE(this.date, 12);
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(packed.length, 18);
    local.writeUInt32LE(data.length, 22);
    local.writeUInt16LE(nameBytes.length, 26);
    local.writeUInt16LE(0, 28);
    const central = Buffer.alloc(46);
    central.writeUInt32LE(0x02014b50, 0);
    central.writeUInt16LE(20, 4); // made by: 2.0, MS-DOS attributes
    central.writeUInt16LE(20, 6);
    central.writeUInt16LE(0, 8);
    central.writeUInt16LE(8, 10);
    central.writeUInt16LE(this.time, 12);
    central.writeUInt16LE(this.date, 14);
    central.writeUInt32LE(crc, 16);
    central.writeUInt32LE(packed.length, 20);
    central.writeUInt32LE(data.length, 24);
    central.writeUInt16LE(nameBytes.length, 28);
    // extra, comment, disk start, internal and external attributes: all 0
    central.writeUInt32LE(this.offset, 42);
    const added = local.length + nameBytes.length + packed.length;
    // The finished archive, directory and end record included, stays in budget.
    if (this.size + added + central.length + nameBytes.length > MAX_ZIP_BYTES)
      throw new ZipLimitError("ZIP too large");
    this.names.add(name);
    this.input += data.length;
    this.locals.push(local, nameBytes, packed);
    this.centrals.push(central, nameBytes);
    this.offset += added;
    this.directory += central.length + nameBytes.length;
  }
  finish(): Buffer {
    if (!this.names.size)
      throw new ZipLimitError("ZIP entry count out of bounds");
    const end = Buffer.alloc(EOCD_BYTES);
    end.writeUInt32LE(0x06054b50, 0);
    end.writeUInt16LE(this.names.size, 8);
    end.writeUInt16LE(this.names.size, 10);
    end.writeUInt32LE(this.directory, 12);
    end.writeUInt32LE(this.offset, 16);
    return Buffer.concat([...this.locals, ...this.centrals, end]);
  }
}

export type ZipEntry = { name: string; data: Buffer };
export function zipFiles(entries: ZipEntry[], at = new Date()): Buffer {
  const zip = new ZipWriter(at);
  for (const { name, data } of entries) zip.add(name, data);
  return zip.finish();
}
